export type ParsedOwnerDepositAndGrantInstruction<
  TProgram extends string = typeof AGARI_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    vaultConfig: TAccountMetas[1];
    account: TAccountMetas[2];
    custody: TAccountMetas[3];
    ownerAta: TAccountMetas[4];
    collateralMint: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
    grant: TAccountMetas[7];
    previousGrant?: TAccountMetas[8] | undefined;
    systemProgram: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: OwnerDepositAndGrantInstructionData;
};

export function parseOwnerDepositAndGrantInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOwnerDepositAndGrantInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === AGARI_VAULT_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      vaultConfig: getNextAccount(),
      account: getNextAccount(),
      custody: getNextAccount(),
      ownerAta: getNextAccount(),
      collateralMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      grant: getNextAccount(),
      previousGrant: getNextOptionalAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getOwnerDepositAndGrantInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
